import { DatabaseSync } from 'node:sqlite';

/**
 * The server knows only: usernames, password hashes, PUBLIC keys, and encrypted envelopes that are
 * deleted as soon as the recipient acknowledges them. It never has message content or private keys.
 *
 * Two secrets per user:
 *  - pass_hash:   the human login password (set by the admin, changed by the employee on first login)
 *  - device_hash: a random secret generated by the logged-in device; used for every API/WebSocket call
 * A user created by an admin is "pending" (no keys, no device) until the employee logs in.
 */
export interface UserRow {
  username: string;
  pass_hash: string;
  device_hash: string | null;
  must_change: number;
  identity_key: string;
  spk_id: number;
  spk_pub: string;
  spk_sig: string;
}

export const isActive = (u: UserRow) => !!u.device_hash && !!u.identity_key;

export function openDb(file: string) {
  const db = new DatabaseSync(file);
  db.exec(`
    PRAGMA journal_mode = WAL;
    PRAGMA foreign_keys = ON;
    CREATE TABLE IF NOT EXISTS users (
      username      TEXT PRIMARY KEY,
      pass_hash     TEXT NOT NULL,
      identity_key  TEXT NOT NULL,
      spk_id        INTEGER NOT NULL,
      spk_pub       TEXT NOT NULL,
      spk_sig       TEXT NOT NULL,
      created_at    INTEGER NOT NULL
    );
    CREATE TABLE IF NOT EXISTS one_time_prekeys (
      username TEXT NOT NULL REFERENCES users(username) ON DELETE CASCADE,
      id       INTEGER NOT NULL,
      pub      TEXT NOT NULL,
      PRIMARY KEY (username, id)
    );
    CREATE TABLE IF NOT EXISTS queue (
      id        INTEGER PRIMARY KEY AUTOINCREMENT,
      recipient TEXT NOT NULL REFERENCES users(username) ON DELETE CASCADE,
      sender    TEXT NOT NULL,
      body      TEXT NOT NULL,
      ts        INTEGER NOT NULL
    );
    CREATE INDEX IF NOT EXISTS queue_recipient ON queue(recipient, id);
  `);

  // ---- migrations (older databases) ----
  const cols = (db.prepare('PRAGMA table_info(users)').all() as { name: string }[]).map((c) => c.name);
  if (!cols.includes('device_hash')) {
    db.exec('ALTER TABLE users ADD COLUMN device_hash TEXT');
    // Accounts created before logins existed authenticated with a device-generated secret stored in pass_hash.
    db.exec("UPDATE users SET device_hash = pass_hash WHERE identity_key != ''");
  }
  if (!cols.includes('must_change')) db.exec('ALTER TABLE users ADD COLUMN must_change INTEGER NOT NULL DEFAULT 0');

  const q = {
    getUser: db.prepare('SELECT * FROM users WHERE username = ?'),
    listUsers: db.prepare('SELECT * FROM users ORDER BY username'),
    insertUser: db.prepare(
      `INSERT INTO users (username, pass_hash, device_hash, must_change, identity_key, spk_id, spk_pub, spk_sig, created_at)
       VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)`,
    ),
    activate: db.prepare(
      `UPDATE users SET device_hash = ?, identity_key = ?, spk_id = ?, spk_pub = ?, spk_sig = ? WHERE username = ?`,
    ),
    setPassword: db.prepare('UPDATE users SET pass_hash = ?, must_change = ? WHERE username = ?'),
    deleteUser: db.prepare('DELETE FROM users WHERE username = ?'),
    setSpk: db.prepare('UPDATE users SET spk_id = ?, spk_pub = ?, spk_sig = ? WHERE username = ?'),
    insertOpk: db.prepare('INSERT OR REPLACE INTO one_time_prekeys (username, id, pub) VALUES (?, ?, ?)'),
    deleteOpks: db.prepare('DELETE FROM one_time_prekeys WHERE username = ?'),
    takeOpk: db.prepare('SELECT id, pub FROM one_time_prekeys WHERE username = ? ORDER BY id LIMIT 1'),
    deleteOpk: db.prepare('DELETE FROM one_time_prekeys WHERE username = ? AND id = ?'),
    countOpk: db.prepare('SELECT COUNT(*) AS n FROM one_time_prekeys WHERE username = ?'),
    enqueue: db.prepare('INSERT INTO queue (recipient, sender, body, ts) VALUES (?, ?, ?, ?)'),
    pending: db.prepare('SELECT id, sender, body, ts FROM queue WHERE recipient = ? ORDER BY id LIMIT 500'),
    clearQueue: db.prepare('DELETE FROM queue WHERE recipient = ?'),
    ack: db.prepare('DELETE FROM queue WHERE id = ? AND recipient = ?'),
    queueSize: db.prepare('SELECT COUNT(*) AS n FROM queue WHERE recipient = ?'),
    purgeOld: db.prepare('DELETE FROM queue WHERE ts < ?'),
  };

  const tx = (fn: () => void) => {
    db.exec('BEGIN');
    try {
      fn();
      db.exec('COMMIT');
    } catch (e) {
      db.exec('ROLLBACK');
      throw e;
    }
  };

  return {
    db,
    getUser: (username: string) => q.getUser.get(username) as UserRow | undefined,
    listUsers: () => q.listUsers.all() as unknown as UserRow[],

    /** Self-registration (open servers / the admin's own first account): device secret only. */
    createUser(
      u: { username: string; deviceHash: string; identityKey: string; spk: { id: number; pub: string; sig: string } },
      opks: { id: number; pub: string }[],
    ) {
      tx(() => {
        q.insertUser.run(u.username, u.deviceHash, u.deviceHash, 0, u.identityKey, u.spk.id, u.spk.pub, u.spk.sig, Date.now());
        for (const k of opks) q.insertOpk.run(u.username, k.id, k.pub);
      });
    },

    /** Admin creates an employee: login password only, no keys until the employee logs in. */
    createPendingUser(username: string, passHash: string) {
      q.insertUser.run(username, passHash, null, 1, '', 0, '', '', Date.now());
    },

    /** Employee logs in on a device: new keys + device secret. Old device and undeliverable messages are dropped. */
    activate(
      username: string,
      a: { deviceHash: string; identityKey: string; spk: { id: number; pub: string; sig: string } },
      opks: { id: number; pub: string }[],
    ) {
      tx(() => {
        q.activate.run(a.deviceHash, a.identityKey, a.spk.id, a.spk.pub, a.spk.sig, username);
        q.deleteOpks.run(username);
        for (const k of opks) q.insertOpk.run(username, k.id, k.pub);
        q.clearQueue.run(username); // encrypted for the old device's keys - can never be decrypted now
      });
    },

    setPassword: (username: string, passHash: string, mustChange: boolean) =>
      q.setPassword.run(passHash, mustChange ? 1 : 0, username),
    deleteUser: (username: string) => q.deleteUser.run(username),
    setSignedPreKey: (username: string, spk: { id: number; pub: string; sig: string }) =>
      q.setSpk.run(spk.id, spk.pub, spk.sig, username),
    addOneTimePreKeys(username: string, opks: { id: number; pub: string }[]) {
      tx(() => {
        for (const k of opks) q.insertOpk.run(username, k.id, k.pub);
      });
    },
    /** Hand out a one-time prekey exactly once. */
    takeOneTimePreKey(username: string) {
      const row = q.takeOpk.get(username) as { id: number; pub: string } | undefined;
      if (row) q.deleteOpk.run(username, row.id);
      return row;
    },
    countOneTimePreKeys: (username: string) => (q.countOpk.get(username) as { n: number }).n,
    enqueue: (recipient: string, sender: string, body: string, ts: number) =>
      Number(q.enqueue.run(recipient, sender, body, ts).lastInsertRowid),
    pending: (recipient: string) =>
      q.pending.all(recipient) as { id: number; sender: string; body: string; ts: number }[],
    ack: (id: number, recipient: string) => q.ack.run(id, recipient),
    queueSize: (recipient: string) => (q.queueSize.get(recipient) as { n: number }).n,
    purgeOlderThan: (ts: number) => q.purgeOld.run(ts),
  };
}

export type Db = ReturnType<typeof openDb>;
